class StreamChecker(words:Array<String>){
    private class Node{
        val next=arrayOfNulls<Node>(26);
        var end=false
    };
    private val root=Node();
    private val history=StringBuilder();
    private var maximum=0;
    init{
        for(word in words){
            maximum=maxOf(maximum,word.length);
            var node=root;
            for(i in word.lastIndex downTo 0){
                val index=word[i]-'a';
                if(node.next[index]==null)node.next[index]=Node();
                node=node.next[index]!!
            };
            node.end=true
        }
    };
    fun query(letter:Char):Boolean{
        history.append(letter);
        if(history.length>maximum)history.deleteCharAt(0);
        var node:Node?=root;
        for(i in history.lastIndex downTo 0){
            node=node?.next?.get(history[i]-'a')?:return false;
            if(node.end)return true
        };
        return false
    }
}

